#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using pii = pair<int, int>;

const int INF = 1e9;

struct FlowNetwork {
    int N;
    vector<vector<int>> capacity, adj;
    vector<int> level, ptr;

    FlowNetwork(int n) : N(n), capacity(n, vector<int>(n, 0)), adj(n), level(n), ptr(n) {}

    void addEdge(int u, int v, int cap) {
        capacity[u][v] = cap;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    bool bfs(int s, int t) {
        fill(level.begin(), level.end(), -1);
        queue<int> q;
        q.push(s);
        level[s] = 0;
        while (!q.empty()) {
            int u = q.front(); q.pop();
            for (int v : adj[u]) {
                if (level[v] == -1 && capacity[u][v] > 0) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }
        return level[t] != -1;
    }

    int dfs(int u, int t, int flow) {
        if (u == t) return flow;
        for (int& i = ptr[u]; i < (int)adj[u].size(); ++i) {
            int v = adj[u][i];
            if (level[v] == level[u] + 1 && capacity[u][v] > 0) {
                int pushed = dfs(v, t, min(flow, capacity[u][v]));
                if (pushed > 0) {
                    capacity[u][v] -= pushed;
                    capacity[v][u] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    int maxFlow(int s, int t) {
        int total = 0;
        while (bfs(s, t)) {
            fill(ptr.begin(), ptr.end(), 0);
            int pushed;
            while ((pushed = dfs(s, t, INF)) > 0) {
                total += pushed;
            }
        }
        return total;
    }
};

int main() {
    ios::sync_with_stdio(false); cin.tie(nullptr);
    int n, t;
    cin >> n >> t;
    vector<string> field(n), capsule(n);
    int src = 2 * n * n, dst = src + 1;
    FlowNetwork flow(2 * n * n + 2);

    int zx = -1, zy = -1;
    for (int i = 0; i < n; ++i) {
        cin >> field[i];
        for (int j = 0; j < n; ++j) {
            if (field[i][j] == 'Z') {
                zx = i; zy = j;
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        cin >> capsule[i];
        for (int j = 0; j < n; ++j) {
            if (isdigit(capsule[i][j])) {
                flow.addEdge(i * n + j + n * n, dst, capsule[i][j] - '0');
            }
        }
    }

    vector<vector<int>> distZ(n, vector<int>(n, INF));
    queue<pii> q;
    distZ[zx][zy] = 0;
    q.push({zx, zy});
    int dx[] = {-1, 1, 0, 0}, dy[] = {0, 0, -1, 1};

    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        if (distZ[x][y] == t) continue;
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distZ[nx][ny] == INF) {
                distZ[nx][ny] = distZ[x][y] + 1;
                if (isdigit(capsule[nx][ny])) {
                    flow.addEdge(zx * n + zy, nx * n + ny + n * n, INF);
                }
                q.push({nx, ny});
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(field[i][j])) {
                flow.addEdge(src, i * n + j, field[i][j] - '0');
                vector<vector<int>> distS(n, vector<int>(n, INF));
                queue<pii> q2;
                distS[i][j] = 0;
                q2.push({i, j});
                while (!q2.empty()) {
                    auto [x, y] = q2.front(); q2.pop();
                    if (distS[x][y] == t) continue;
                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dx[d], ny = y + dy[d];
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && capsule[nx][ny] != 'Y' && distS[nx][ny] == INF) {
                            distS[nx][ny] = distS[x][y] + 1;
                            if (isdigit(capsule[nx][ny])) {
                                flow.addEdge(i * n + j, nx * n + ny + n * n, INF);
                            }
                            q2.push({nx, ny});
                        }
                    }
                }
            }
        }
    }

    cout << flow.maxFlow(src, dst) << '\n';
    return 0;
}
